INSERT INTO `v1_f268a0b0b6ba23072441522106119819db206c6079e0b5cc9c8bf246e3d09dca` VALUES (1, 2, 11, "因縁の強敵たち…更に幻境竜后を倒さねば、未来はありません。\n皆様と力を合わせて全てのボスを完全討伐し、\n全フェーズの攻略を目指しましょう。", 1, 4);
INSERT INTO `v1_f268a0b0b6ba23072441522106119819db206c6079e0b5cc9c8bf246e3d09dca` VALUES (1, 2, 12, "皆様で協力して『Total HP』を0にすると完全討伐となります。\nこの戦いに参加した皆様全員が報酬を獲得できるようです。\n受け取りは期間中のみのようなので、注意してくださいませ。", 2, 4);
INSERT INTO `v1_f268a0b0b6ba23072441522106119819db206c6079e0b5cc9c8bf246e3d09dca` VALUES (1, 2, 13, "特定のお仲間は、バトルでより力を発揮しやすいようです。\nもし育成ができていないお仲間がいる場合は、今回はマナを使わずに\nサポートキャラを編成できますので試してみましょう。", 3, 4);
INSERT INTO `v1_f268a0b0b6ba23072441522106119819db206c6079e0b5cc9c8bf246e3d09dca` VALUES (1, 2, 14, "皆様で力を合わせて『Total HP』を減らすと、バーストダウンが発生\nするようです。一定時間、バトルが有利になる効果が発動するように\nなります。時間経過で特別なバーストダウンも発生するようです。", 4, 4);
INSERT INTO `v1_f268a0b0b6ba23072441522106119819db206c6079e0b5cc9c8bf246e3d09dca` VALUES (1, 2, 15, "ボスを完全討伐する度に、バーストエンドが発生するようです。\n残りのボスとのバトルが有利になる効果が発動いたしますので、\n苦戦していたボスにももう一度挑戦してみると良いかもしれません。", 5, 4);
INSERT INTO `v1_f268a0b0b6ba23072441522106119819db206c6079e0b5cc9c8bf246e3d09dca` VALUES (1, 2, 16, "全てのフェーズを攻略すると、いよいよ最終決戦です。\n各ボスは次のフェーズが始まると戦えなくなるので、完全討伐まで\nたくさん撃退して報酬をたくさん獲得いたしましょう。", 6, 4);
INSERT INTO `v1_f268a0b0b6ba23072441522106119819db206c6079e0b5cc9c8bf246e3d09dca` VALUES (2, 1, 21, "幻境竜后との最終決戦の時がやってまいりました。\n最終決戦には何度でも挑戦が可能でございます。\n失敗しても編成を考え直せるので、焦らずに最終決戦にのぞみましょう。", 7, 4);
INSERT INTO `v1_f268a0b0b6ba23072441522106119819db206c6079e0b5cc9c8bf246e3d09dca` VALUES (1, 3, 31, "因縁の強敵たち…更に幻境竜后を倒さねば、未来はありません。\n全てのボスを討伐し、全フェーズの攻略を目指しましょう。", 8, 4);
INSERT INTO `v1_f268a0b0b6ba23072441522106119819db206c6079e0b5cc9c8bf246e3d09dca` VALUES (1, 3, 32, "全てのフェーズを攻略すると、いよいよ最終決戦です。\nキャラを育成して、幻境竜后との戦いに臨みましょう。", 9, 4);
